def _group_rows():
    groups = {}
    for group, leaf, url, cn, label, department in _ROWS:
        groups.setdefault(group, {})[leaf] = {
            "category": leaf,
            "url": url,
            "cn": cn,
            "label": label,
            "department": department,
        }
    return groups


